create table if not exists public.historial_peso (id uuid primary key default gen_random_uuid(), usuario_id uuid not null references public.usuarios(id) on delete cascade, peso_kg double precision not null, altura_cm double precision not null, imc double precision not null, registrado_en timestamptz not null default now());
create table if not exists public.historial_objetivos (id uuid primary key default gen_random_uuid(), usuario_id uuid not null references public.usuarios(id) on delete cascade, objetivo text not null, objetivo_anterior text, fecha_inicio date not null default current_date, fecha_fin date, rutina_ids uuid[] default '{}', creado_en timestamptz not null default now());
create table if not exists public.carga_academica_semanal (id uuid primary key default gen_random_uuid(), usuario_id uuid not null references public.usuarios(id) on delete cascade, semana_inicio date not null, horas_estudio_planeadas int not null default 0, horas_estudio_reales int not null default 0, evaluaciones_semana int not null default 0, entregas_semana int not null default 0, nivel_estres int not null default 5, horas_sueno_promedio double precision not null default 7, notas text, xp_estudio_otorgado boolean not null default false, creado_en timestamptz not null default now(), actualizado_en timestamptz not null default now(), unique(usuario_id, semana_inicio));
create table if not exists public.plan_entrenamiento_semanal (id uuid primary key default gen_random_uuid(), usuario_id uuid not null references public.usuarios(id) on delete cascade, semana_inicio date not null, sesiones_planificadas int not null default 3, intensidad text not null default 'moderada', duracion_min_por_sesion int not null default 45, estado text not null default 'activo', notas text, creado_en timestamptz not null default now(), actualizado_en timestamptz not null default now());
create table if not exists public.estado_diario_usuario (id uuid primary key default gen_random_uuid(), usuario_id uuid not null references public.usuarios(id) on delete cascade, fecha date not null default current_date, calidad_sueno int, nivel_estres int, nivel_energia int, dolor_muscular int, zonas_dolor text[] default '{}', listo_para_entrenar boolean default true, notas text, creado_en timestamptz not null default now(), unique(usuario_id, fecha));
create table if not exists public.entregas_examenes (id uuid primary key default gen_random_uuid(), usuario_id uuid not null references public.usuarios(id) on delete cascade, asignatura_id uuid, titulo text not null, tipo text not null, fecha_limite timestamptz not null, dificultad text not null default 'media', esta_completado boolean not null default false, plan_estudio_id uuid, creado_en timestamptz not null default now(), actualizado_en timestamptz not null default now());
create table if not exists public.series_sesion (id uuid primary key default gen_random_uuid(), sesion_id uuid not null references public.sesiones_registradas(id) on delete cascade, seleccion_id uuid, numero_serie int not null, repeticiones_realizadas int, peso_kg double precision, completada boolean not null default false, failed_reps int not null default 0, creado_en timestamptz not null default now());
create table if not exists public.semanas_rutina (id uuid primary key default gen_random_uuid(), rutina_id uuid not null references public.rutinas(id) on delete cascade, numero_semana int not null, nombre text not null default '', estado text not null default 'pendiente', creado_en timestamptz not null default now(), tipo_semana text default 'carga', unique(rutina_id, numero_semana));
create table if not exists public.dias_rutina (id uuid primary key default gen_random_uuid(), semana_id uuid not null references public.semanas_rutina(id) on delete cascade, numero_dia int not null, nombre text not null default '', estado text not null default 'pendiente', creado_en timestamptz not null default now(), unique(semana_id, numero_dia));
create table if not exists public.recomendaciones_pendientes (id uuid primary key default gen_random_uuid(), usuario_id uuid not null, tipo text not null, titulo text not null, descripcion text, ejercicio_id uuid, rutina_id uuid, datos jsonb default '{}', aplicada boolean not null default false, creado_en timestamptz not null default now());
